Object.assign(SNIP,{});PRESET_NOTES["l35"]={"Ví dụ: Ba cách duyệt đệ quy": "Ba hàm chỉ khác vị trí dòng in. Theo dõi tên u dưới nút đang xét và cây lời gọi: mỗi nút được gọi đúng một lần, nút rỗng (nullptr) cũng là một lời gọi và trả về ngay. Kết quả 1 2 4 5 3 6 / 4 2 5 1 3 6 / 4 5 2 6 3 1.", "Ví dụ: Duyệt theo tầng bằng hàng đợi": "Hàng đợi giữ các nút đã thấy mà chưa xử lý; nút ở tầng trên luôn vào trước các nút ở tầng dưới. Đây chính là BFS (Chương 10) trên cây. Kết quả 1 2 3 4 5 6.", "Ví dụ: Chiều cao và số lá": "Đệ quy “từ dưới lên”: chiều cao của u chỉ tính được khi đã biết chiều cao hai cây con (duyệt sau). Cây có 4 tầng (1 → 3 → 6 → 7) và 3 lá: 4, 5, 7.", "Ví dụ: Cây lưu bằng mảng": "Cùng cây như các ví dụ trên, nhưng mỗi nút là một số và hai mảng cho biết con trái, con phải. Đề thi thường cho cây theo kiểu này. Kết quả duyệt giữa 4 2 5 1 3 6.", "Lỗi: quên kiểm tra nút rỗng": "Nút 2 không có con phải, nên tong(u->right) được gọi với nullptr và đọc u->val của con trỏ rỗng: chương trình dừng. Cách an toàn: đặt điều kiện dừng if (u == nullptr) return 0; ở đầu hàm, rồi gọi đệ quy thoải mái."};EX_HINTS["l35"]=[["Điều kiện dừng: u == 0 là nút rỗng.", "Ba hàm giống hệt nhau, chỉ khác vị trí dòng in so với hai lời gọi đệ quy.", "Trước: in, trái, phải. Giữa: trái, in, phải. Sau: trái, phải, in."], ["Duyệt theo tầng bằng hàng đợi. Mẹo tách tầng: ở đầu mỗi vòng, q.size() đúng bằng số nút của tầng hiện tại.", "Lấy ra đúng k nút đó, cộng giá trị, đưa các con của chúng vào hàng đợi (đó là tầng sau).", "Tổng một tầng tới 10^4 · 10^9: dùng long long."], ["Mọi đường đi đều có một nút “cao nhất” u; đường đó gồm một nhánh đi xuống bên trái và một nhánh bên phải của u.", "Nhánh dài nhất xuống cây con trái dài cao(trai) + 1 cạnh (tính cả cạnh u–trai). Quy ước cây rỗng cao −1 thì công thức a + b + 2 đúng cả khi thiếu con.", "Tính trong cùng một lượt đệ quy: hàm trả về chiều cao, đồng thời cập nhật biến toàn cục best."]];
/* ===================== BÀI 35 · Cây, cây nhị phân và các cách duyệt cây ===================== */
/* Bài 35 · Cây, cây nhị phân và các cách duyệt cây
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR35=[{label:"Ví dụ: Ba cách duyệt đệ quy",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* left;\n    Node* right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nvoid truoc(Node* u) {\n    if (u == nullptr) return;\n    cout << u->val << \" \";        // nút trước\n    truoc(u->left);\n    truoc(u->right);\n}\n\nvoid giua(Node* u) {\n    if (u == nullptr) return;\n    giua(u->left);\n    cout << u->val << \" \";        // nút ở giữa\n    giua(u->right);\n}\n\nvoid sau(Node* u) {\n    if (u == nullptr) return;\n    sau(u->left);\n    sau(u->right);\n    cout << u->val << \" \";        // nút sau cùng\n}\n\nint main() {\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->right = new Node(3);\n    root->left->left = new Node(4);\n    root->left->right = new Node(5);\n    root->right->right = new Node(6);\n    truoc(root); cout << \"\\n\";\n    giua(root);  cout << \"\\n\";\n    sau(root);   cout << \"\\n\";\n    return 0;\n}",viz:[{type:"tree",of:"root",ptr:["u"]},{type:"calls"}],py:{code:"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef truoc(u, out):\n    if u is None:\n        return\n    out.append(u.val)          # nút trước\n    truoc(u.left, out)\n    truoc(u.right, out)\n\ndef giua(u, out):\n    if u is None:\n        return\n    giua(u.left, out)\n    out.append(u.val)          # nút ở giữa\n    giua(u.right, out)\n\ndef sau(u, out):\n    if u is None:\n        return\n    sau(u.left, out)\n    sau(u.right, out)\n    out.append(u.val)          # nút sau cùng\n\nroot = Node(1)\nroot.left = Node(2)\nroot.right = Node(3)\nroot.left.left = Node(4)\nroot.left.right = Node(5)\nroot.right.right = Node(6)\n\nfor f in (truoc, giua, sau):\n    out = []\n    f(root, out)\n    print(*out)"},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Left, Right;\n\n    public Node(int val)\n    {\n        Val = val;\n    }\n}\n\nclass Program\n{\n    static void Truoc(Node u)\n    {\n        if (u == null) return;\n        Console.Write(u.Val + \" \");        // nút trước\n        Truoc(u.Left);\n        Truoc(u.Right);\n    }\n\n    static void Giua(Node u)\n    {\n        if (u == null) return;\n        Giua(u.Left);\n        Console.Write(u.Val + \" \");        // nút ở giữa\n        Giua(u.Right);\n    }\n\n    static void Sau(Node u)\n    {\n        if (u == null) return;\n        Sau(u.Left);\n        Sau(u.Right);\n        Console.Write(u.Val + \" \");        // nút sau cùng\n    }\n\n    static void Main()\n    {\n        Node root = new Node(1);\n        root.Left = new Node(2);\n        root.Right = new Node(3);\n        root.Left.Left = new Node(4);\n        root.Left.Right = new Node(5);\n        root.Right.Right = new Node(6);\n        Truoc(root); Console.WriteLine();\n        Giua(root);  Console.WriteLine();\n        Sau(root);   Console.WriteLine();\n    }\n}",viz:[{type:"tree",of:"root",left:"Left",right:"Right",val:"Val",ptr:["u"]},{type:"calls"}]}},{label:"Ví dụ: Duyệt theo tầng bằng hàng đợi",input:"",code:"#include <iostream>\n#include <queue>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* left;\n    Node* right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nint main() {\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->right = new Node(3);\n    root->left->left = new Node(4);\n    root->left->right = new Node(5);\n    root->right->right = new Node(6);\n    queue<Node*> q;\n    q.push(root);\n    while (!q.empty()) {\n        Node* u = q.front();\n        q.pop();\n        cout << u->val << \" \";\n        if (u->left != nullptr) q.push(u->left);\n        if (u->right != nullptr) q.push(u->right);\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"tree",of:"root",ptr:["u"]}],py:{code:"from collections import deque\n\nclass Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\nroot = Node(1)\nroot.left = Node(2)\nroot.right = Node(3)\nroot.left.left = Node(4)\nroot.left.right = Node(5)\nroot.right.right = Node(6)\n\nq = deque([root])\nout = []\nwhile q:\n    u = q.popleft()\n    out.append(u.val)\n    if u.left is not None:\n        q.append(u.left)\n    if u.right is not None:\n        q.append(u.right)\nprint(*out)"},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Node\n{\n    public int Val;\n    public Node Left, Right;\n\n    public Node(int val)\n    {\n        Val = val;\n    }\n}\n\nclass Program\n{\n    static void Main()\n    {\n        Node root = new Node(1);\n        root.Left = new Node(2);\n        root.Right = new Node(3);\n        root.Left.Left = new Node(4);\n        root.Left.Right = new Node(5);\n        root.Right.Right = new Node(6);\n        Queue<Node> q = new Queue<Node>();\n        q.Enqueue(root);\n        while (q.Count > 0)\n        {\n            Node u = q.Dequeue();\n            Console.Write(u.Val + \" \");\n            if (u.Left != null) q.Enqueue(u.Left);\n            if (u.Right != null) q.Enqueue(u.Right);\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"tree",of:"root",left:"Left",right:"Right",val:"Val",ptr:["u"]}]}},{label:"Ví dụ: Chiều cao và số lá",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* left;\n    Node* right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nint cao(Node* u) {                    // số tầng; cây rỗng có 0 tầng\n    if (u == nullptr) return 0;\n    return 1 + max(cao(u->left), cao(u->right));\n}\n\nint soLa(Node* u) {\n    if (u == nullptr) return 0;\n    if (u->left == nullptr && u->right == nullptr) return 1;\n    return soLa(u->left) + soLa(u->right);\n}\n\nint main() {\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->right = new Node(3);\n    root->left->left = new Node(4);\n    root->left->right = new Node(5);\n    root->right->right = new Node(6);\n    root->right->right->left = new Node(7);\n    cout << cao(root) << \" \" << soLa(root) << \"\\n\";\n    return 0;\n}",viz:[{type:"tree",of:"root",ptr:["u"]},{type:"calls"}],py:{code:"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef cao(u):                       # số tầng; cây rỗng có 0 tầng\n    if u is None:\n        return 0\n    return 1 + max(cao(u.left), cao(u.right))\n\ndef soLa(u):\n    if u is None:\n        return 0\n    if u.left is None and u.right is None:\n        return 1\n    return soLa(u.left) + soLa(u.right)\n\nroot = Node(1)\nroot.left = Node(2)\nroot.right = Node(3)\nroot.left.left = Node(4)\nroot.left.right = Node(5)\nroot.right.right = Node(6)\nroot.right.right.left = Node(7)\nprint(cao(root), soLa(root))"},cs:{code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Left, Right;\n\n    public Node(int val)\n    {\n        Val = val;\n    }\n}\n\nclass Program\n{\n    static int Cao(Node u)                 // số tầng; cây rỗng có 0 tầng\n    {\n        if (u == null) return 0;\n        return 1 + Math.Max(Cao(u.Left), Cao(u.Right));\n    }\n\n    static int SoLa(Node u)\n    {\n        if (u == null) return 0;\n        if (u.Left == null && u.Right == null) return 1;\n        return SoLa(u.Left) + SoLa(u.Right);\n    }\n\n    static void Main()\n    {\n        Node root = new Node(1);\n        root.Left = new Node(2);\n        root.Right = new Node(3);\n        root.Left.Left = new Node(4);\n        root.Left.Right = new Node(5);\n        root.Right.Right = new Node(6);\n        root.Right.Right.Left = new Node(7);\n        Console.WriteLine(Cao(root) + \" \" + SoLa(root));\n    }\n}",viz:[{type:"tree",of:"root",left:"Left",right:"Right",val:"Val",ptr:["u"]},{type:"calls"}]}},{label:"Ví dụ: Cây lưu bằng mảng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint trai[7] = {0, 2, 4, 0, 0, 0, 0};   // nút 1..6; 0: không có con\nint phai[7] = {0, 3, 5, 6, 0, 0, 0};\n\nvoid giua(int u) {\n    if (u == 0) return;\n    giua(trai[u]);\n    cout << u << \" \";\n    giua(phai[u]);\n}\n\nint main() {\n    giua(1);\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"trai",ptr:["u"]},{type:"cells",of:"phai",ptr:["u"]},{type:"calls"}],py:{code:"trai = [0, 2, 4, 0, 0, 0, 0]    # nút 1..6; 0: không có con\nphai = [0, 3, 5, 6, 0, 0, 0]\nout = []\n\ndef giua(u):\n    if u == 0:\n        return\n    giua(trai[u])\n    out.append(u)\n    giua(phai[u])\n\ngiua(1)\nprint(*out)"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] trai = { 0, 2, 4, 0, 0, 0, 0 };   // nút 1..6; 0: không có con\n    static int[] phai = { 0, 3, 5, 6, 0, 0, 0 };\n\n    static void Giua(int u)\n    {\n        if (u == 0) return;\n        Giua(trai[u]);\n        Console.Write(u + \" \");\n        Giua(phai[u]);\n    }\n\n    static void Main()\n    {\n        Giua(1);\n        Console.WriteLine();\n    }\n}"}},{label:"Lỗi: quên kiểm tra nút rỗng",input:"",code:"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* left;\n    Node* right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nint tong(Node* u) {\n    return u->val + (u->left ? tong(u->left) : 0) + tong(u->right);   // thiếu kiểm tra u->right\n}\n\nint main() {\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    cout << tong(root) << \"\\n\";\n    return 0;\n}",viz:[{type:"tree",of:"root",ptr:["u"]}],py:{label:"Lỗi: quên kiểm tra nút None",code:"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef tong(u):\n    return u.val + (tong(u.left) if u.left else 0) + tong(u.right)   # thiếu kiểm tra u.right\n\nroot = Node(1)\nroot.left = Node(2)\nprint(tong(root))",note:"Nút 2 không có con phải, nên tong(u.right) được gọi với None và đọc None.val: AttributeError. Cách an toàn: đặt điều kiện dừng if u is None: return 0 ở đầu hàm."},cs:{label:"Lỗi: quên kiểm tra nút null",code:"using System;\n\nclass Node\n{\n    public int Val;\n    public Node Left, Right;\n\n    public Node(int val)\n    {\n        Val = val;\n    }\n}\n\nclass Program\n{\n    static int Tong(Node u)\n    {\n        return u.Val + (u.Left != null ? Tong(u.Left) : 0) + Tong(u.Right);   // thiếu kiểm tra u.Right\n    }\n\n    static void Main()\n    {\n        Node root = new Node(1);\n        root.Left = new Node(2);\n        Console.WriteLine(Tong(root));\n    }\n}",viz:[{type:"tree",of:"root",left:"Left",right:"Right",val:"Val",ptr:["u"]}],note:"Nút 2 không có con phải, nên Tong(u.Right) được gọi với null và đọc u.Val: NullReferenceException. Cách an toàn: đặt điều kiện dừng if (u == null) return 0; ở đầu hàm."}}];
