makeEx2(document.getElementById("ex-l35"),sim35,[{t:"Ba thứ tự duyệt",d:"Cây nhị phân n nút đánh số 1..n, gốc là nút 1. Đầu vào: n (1 ≤ n ≤ 1000), rồi n dòng, dòng thứ u gồm hai số: con trái và con phải của nút u (0 nếu không có). Đầu ra: ba dòng lần lượt là thứ tự duyệt trước, giữa, sau.",tests:[{in:"6\n2 3\n4 5\n0 6\n0 0\n0 0\n0 0",out:"1 2 4 5 3 6\n4 2 5 1 3 6\n4 5 2 6 3 1"},{in:"1\n0 0",out:"1\n1\n1"},{in:"4\n2 0\n3 0\n4 0\n0 0",out:"1 2 3 4\n4 3 2 1\n4 3 2 1"},{in:"3\n0 2\n0 3\n0 0",out:"1 2 3\n1 2 3\n3 2 1"},{in:"11\n2 3\n4 5\n6 7\n8 9\n10 0\n0 0\n0 11\n0 0\n0 0\n0 0\n0 0",out:"1 2 4 8 9 5 10 3 6 7 11\n8 4 9 2 10 5 1 6 3 7 11\n8 9 4 10 5 2 6 11 7 3 1"}],start:"#include <iostream>\nusing namespace std;\n\nint trai[1001], phai[1001];\n\nvoid truoc(int u) {\n}\n\nvoid giua(int u) {\n}\n\nvoid sau(int u) {\n}\n\nint main() {\n    int n;\n    cin >> n;\n    for (int u = 1; u <= n; u++) cin >> trai[u] >> phai[u];\n    truoc(1); cout << \"\\n\";\n    giua(1);  cout << \"\\n\";\n    sau(1);   cout << \"\\n\";\n    return 0;\n}",py:{start:"import sys\nsys.setrecursionlimit(5000)\n\nn = int(input())\ntrai = [0] * (n + 1)\nphai = [0] * (n + 1)\nfor u in range(1, n + 1):\n    trai[u], phai[u] = map(int, input().split())\n\nout = []\n\ndef truoc(u):\n    pass\n\ndef giua(u):\n    pass\n\ndef sau(u):\n    pass\n\nfor f in (truoc, giua, sau):\n    out = []\n    f(1)\n    print(*out)",hints:["Điều kiện dừng: u == 0 là nút rỗng.","Ba hàm giống hệt nhau, chỉ khác vị trí dòng out.append(u) so với hai lời gọi đệ quy.","Cây có thể sâu tới 1000 tầng: sys.setrecursionlimit đã được tăng sẵn."]},cs:{start:"using System;\n\nclass Program\n{\n    static int[] trai = new int[1001], phai = new int[1001];\n\n    static void Truoc(int u)\n    {\n    }\n\n    static void Giua(int u)\n    {\n    }\n\n    static void Sau(int u)\n    {\n    }\n\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        for (int u = 1; u <= n; u++)\n        {\n            int[] t = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            trai[u] = t[0];\n            phai[u] = t[1];\n        }\n        Truoc(1); Console.WriteLine();\n        Giua(1);  Console.WriteLine();\n        Sau(1);   Console.WriteLine();\n    }\n}",hints:["Điều kiện dừng: u == 0 là nút rỗng.","Ba hàm giống hệt nhau, chỉ khác vị trí dòng in so với hai lời gọi đệ quy.","Trước: in, trái, phải. Giữa: trái, in, phải. Sau: trái, phải, in."]}},{t:"Tổng theo từng tầng",d:"Cây nhị phân n nút, gốc là nút 1. Đầu vào: n (1 ≤ n ≤ 10^4); dòng 2 là giá trị v₁ … vₙ (|vᵢ| ≤ 10^9); n dòng sau là con trái, con phải của từng nút (0 nếu không có). Đầu ra: tổng giá trị các nút ở tầng 0, tầng 1, … (tầng của gốc là 0), trên một dòng.",tests:[{in:"6\n5 3 8 1 4 7\n2 3\n4 5\n0 6\n0 0\n0 0\n0 0",out:"5 11 12"},{in:"1\n-9\n0 0",out:"-9"},{in:"4\n1 2 3 4\n2 0\n3 0\n4 0\n0 0",out:"1 2 3 4"},{in:"11\n1000000000 1000000000 1000000000 1000000000 1000000000 1000000000 1000000000 1000000000 1000000000 1000000000 1000000000\n2 3\n4 5\n6 7\n8 9\n10 0\n0 0\n0 11\n0 0\n0 0\n0 0\n0 0",out:"1000000000 2000000000 4000000000 4000000000"}],start:"#include <iostream>\n#include <queue>\nusing namespace std;\n\nint trai[10001], phai[10001];\nlong long v[10001];\n\nint main() {\n    int n;\n    cin >> n;\n    for (int u = 1; u <= n; u++) cin >> v[u];\n    for (int u = 1; u <= n; u++) cin >> trai[u] >> phai[u];\n    queue<int> q;\n    q.push(1);\n    // xử lý từng tầng: tầng hiện tại có đúng q.size() nút\n    cout << \"\\n\";\n    return 0;\n}",py:{start:"from collections import deque\n\nn = int(input())\nv = [0] + list(map(int, input().split()))\ntrai = [0] * (n + 1)\nphai = [0] * (n + 1)\nfor u in range(1, n + 1):\n    trai[u], phai[u] = map(int, input().split())\nq = deque([1])\nout = []\n# xử lý từng tầng: tầng hiện tại có đúng len(q) nút\nprint(*out)",hints:["Duyệt theo tầng bằng deque. Mẹo tách tầng: ở đầu mỗi vòng, len(q) đúng bằng số nút của tầng hiện tại.","Lấy ra đúng ngần ấy nút, cộng giá trị, đưa các con của chúng vào cuối (đó là tầng sau).","range(len(q)) được tính một lần khi bắt đầu vòng for, nên các con mới thêm vào không bị lấy nhầm."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] v = Array.ConvertAll((\"0 \" + Console.ReadLine()).Split(), long.Parse);\n        int[] trai = new int[n + 1], phai = new int[n + 1];\n        for (int u = 1; u <= n; u++)\n        {\n            int[] t = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            trai[u] = t[0];\n            phai[u] = t[1];\n        }\n        Queue<int> q = new Queue<int>();\n        q.Enqueue(1);\n        // xử lý từng tầng: tầng hiện tại có đúng q.Count nút\n        Console.WriteLine();\n    }\n}",hints:["Duyệt theo tầng bằng Queue. Mẹo tách tầng: ở đầu mỗi vòng, q.Count đúng bằng số nút của tầng hiện tại; lưu vào k trước.","Lấy ra đúng k nút, cộng giá trị, Enqueue các con (đó là tầng sau).","Tổng một tầng tới 10^4 · 10^9: dùng long."]}},{t:"Đường kính cây nhị phân",d:"Cây nhị phân n nút, gốc là nút 1 (định dạng như bài 1, n ≤ 1000). Đường kính là số cạnh trên đường đi dài nhất giữa hai nút bất kỳ (đường đi không nhất thiết qua gốc). Đầu ra: đường kính.",tests:[{in:"6\n2 3\n4 5\n0 6\n0 0\n0 0\n0 0",out:"4"},{in:"1\n0 0",out:"0"},{in:"4\n2 0\n3 0\n4 0\n0 0",out:"3"},{in:"3\n2 3\n0 0\n0 0",out:"2"},{in:"7\n2 0\n3 4\n5 0\n0 6\n0 0\n7 0\n0 0",out:"5"},{in:"11\n2 3\n4 5\n6 7\n8 9\n10 0\n0 0\n0 11\n0 0\n0 0\n0 0\n0 0",out:"6"}],start:"#include <iostream>\nusing namespace std;\n\nint trai[1001], phai[1001];\nint best = 0;\n\n// trả về chiều cao (số cạnh) của cây con gốc u; cây rỗng: -1\nint cao(int u) {\n    // đường dài nhất \"gập\" tại u dài cao(trai) + cao(phai) + 2\n    return -1;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    for (int u = 1; u <= n; u++) cin >> trai[u] >> phai[u];\n    cao(1);\n    cout << best << \"\\n\";\n    return 0;\n}",py:{start:"import sys\nsys.setrecursionlimit(5000)\n\nn = int(input())\ntrai = [0] * (n + 1)\nphai = [0] * (n + 1)\nfor u in range(1, n + 1):\n    trai[u], phai[u] = map(int, input().split())\n\nbest = 0\n\n# trả về chiều cao (số cạnh) của cây con gốc u; cây rỗng: -1\ndef cao(u):\n    # đường dài nhất \"gập\" tại u dài cao(trai) + cao(phai) + 2\n    return -1\n\ncao(1)\nprint(best)",hints:["Mọi đường đi đều có một nút “cao nhất” u; đường đó gồm một nhánh xuống bên trái và một nhánh xuống bên phải của u.","Quy ước cây rỗng cao −1 thì độ dài a + b + 2 đúng cả khi thiếu con.","Hàm trả về chiều cao, đồng thời cập nhật biến toàn cục best (khai báo global best)."]},cs:{start:"using System;\n\nclass Program\n{\n    static int[] trai = new int[1001], phai = new int[1001];\n    static int best = 0;\n\n    // trả về chiều cao (số cạnh) của cây con gốc u; cây rỗng: -1\n    static int Cao(int u)\n    {\n        // đường dài nhất \"gập\" tại u dài Cao(trai) + Cao(phai) + 2\n        return -1;\n    }\n\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        for (int u = 1; u <= n; u++)\n        {\n            int[] t = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            trai[u] = t[0];\n            phai[u] = t[1];\n        }\n        Cao(1);\n        Console.WriteLine(best);\n    }\n}",hints:["Mọi đường đi đều có một nút “cao nhất” u; đường đó gồm một nhánh xuống bên trái và một nhánh xuống bên phải của u.","Quy ước cây rỗng cao −1 thì độ dài a + b + 2 đúng cả khi thiếu con.","Hàm trả về chiều cao, đồng thời cập nhật biến static best."]}}]);

